SELECT ?item ?ru ?c ?coord (MAX(?pop) AS ?maxpop) WHERE {
  VALUES ?ru { "Псков"@ru "Великие Луки"@ru "Остров"@ru "Брянск"@ru "Дятьково"@ru "Клинцы"@ru "Новозыбков"@ru "Смоленск"@ru "Вязьма"@ru "Гагарин"@ru "Рославль"@ru "Сафоново"@ru "Ярцево"@ru "Луцк"@ru "Владимир-Волынский"@ru "Владимир"@ru "Ковель"@ru "Нововолынск"@ru "Житомир"@ru "Бердичев"@ru "Коростень"@ru "Новоград-Волынский"@ru "Звягель"@ru "Белая Церковь"@ru "Борисполь"@ru "Бровары"@ru "Васильков"@ru "Ирпень"@ru "Переяслав-Хмельницкий"@ru "Переяслав"@ru "Фастов"@ru "Славутич"@ru "Ровно"@ru "Ровне"@ru "Дубно"@ru "Кузнецовск"@ru "Вараш"@ru "Чернигов"@ru "Нежин"@ru "Прилуки"@ru }
  ?item rdfs:label ?ru ; wdt:P17 ?c ; wdt:P625 ?coord .
  FILTER(?c IN (wd:Q159, wd:Q212))
  OPTIONAL { ?item wdt:P1082 ?pop }
} GROUP BY ?item ?ru ?c ?coord
